#!/bin/bash# FWO Server Production Release Pipelineecho "=================================================================="echo "🚀 [DEPLOY] Initiating production deployment to Render..."echo "=================================================================="# 1. Initialize local package validation check to catch errors earlyif [ ! -f "server.js" ]; then    echo "❌ DEPLOY FAILED: server.js not found in current execution directory."    exit 1fi# 2. Add the tracking packages to your project dependenciesecho "[DEPLOY] Verifying native server package layers..."npm install express cors ws --save# 3. Stage changes inside your local Git repository matrixgit add server.js package.json package-lock.json# 4. Commit the new 2PC and WebSocket architecture layers cleanlygit commit -m "feat: upgrade to Manifest V3 server-to-server attestation with 2PC event-driven WebSocket pipeline"# 5. Push code straight to your production branch (triggers automated Render build)echo "[DEPLOY] Transmitting source files to Render upstream tracker..."git push origin mainecho "=================================================================="echo "✅ [SUCCESS] Deployment pipeline kicked off on Render dashboard."echo "👉 Monitor your live deployment log view at https://onrender.com"echo "=================================================================="